@import "tailwindcss";
@import "./brands.css";

/* ---------------------------------------------------------------------------
   Fonts (files live in /public/fonts)
   --------------------------------------------------------------------------- */
@font-face {
  font-family: "m6x11plus";
  src: url("/fonts/m6x11plus.ttf") format("truetype");
  font-display: swap;
}

/* ---------------------------------------------------------------------------
   Surface theme (light / dark mode)
   "Surface" = panels, inputs, menus, toasts, key caps, slots, the `light`
   palette color. Toggle dark mode with the .dark class on <html>.
   --------------------------------------------------------------------------- */
:root {
  /* Shape tokens. Brand themes (.theme-*) override these. */
  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --border-w: 4px;
  --border-w-sm: 2px;
  --border-color: rgba(0, 0, 0, 0.8);
  --shadow-hard: 4px 4px 0 rgba(0, 0, 0, 0.25);
  --shadow-hard-lg: 6px 6px 0 rgba(0, 0, 0, 0.25);
  --shadow-hard-sm: 2px 2px 0 rgba(0, 0, 0, 0.25);
  --btn-highlight: inset 0 0 0 4px rgba(255, 255, 255, 0.2);
  --gradient-to: var(--c-to);

  --surface-from: #f4f4f5;
  --surface-to: #d4d4d8;
  --surface-text: #27272a;
  --surface-muted: #52525b;
  --surface-highlight: rgba(255, 255, 255, 0.3);
  --surface-inset: rgba(0, 0, 0, 0.05);
  --surface-line: rgba(0, 0, 0, 0.1);
  --surface-hover: rgba(0, 0, 0, 0.1);
  --surface-text-shadow: none;
  --surface-text-shadow-xs: none;
  --surface-icon-shadow: none;
}
.dark {
  --surface-from: #3f3f46;
  --surface-to: #27272a;
  --surface-text: #f4f4f5;
  --surface-muted: #a1a1aa;
  --surface-highlight: rgba(255, 255, 255, 0.08);
  --surface-inset: rgba(0, 0, 0, 0.2);
  --surface-line: rgba(0, 0, 0, 0.3);
  --surface-hover: rgba(255, 255, 255, 0.1);
  --surface-text-shadow: 3px 3px 0 rgba(0, 0, 0, 0.5);
  --surface-text-shadow-xs: 1px 1px 0 rgba(0, 0, 0, 0.5);
  --surface-icon-shadow: 3px 3px 0 rgba(0, 0, 0, 0.5);
}

/* ---------------------------------------------------------------------------
   Utilities
   --------------------------------------------------------------------------- */
@utility pixel-corners {
  clip-path: polygon(
    8px 0,
    calc(100% - 8px) 0,
    calc(100% - 8px) 4px,
    calc(100% - 4px) 4px,
    calc(100% - 4px) 8px,
    100% 8px,
    100% calc(100% - 8px),
    calc(100% - 4px) calc(100% - 8px),
    calc(100% - 4px) calc(100% - 4px),
    calc(100% - 8px) calc(100% - 4px),
    calc(100% - 8px) 100%,
    8px 100%,
    8px calc(100% - 4px),
    4px calc(100% - 4px),
    4px calc(100% - 8px),
    0 calc(100% - 8px),
    0 8px,
    4px 8px,
    4px 4px,
    8px 4px
  );
}

/* Surface gradient (light or dark, see :root / .dark) */
@utility bg-surface {
  background-image: linear-gradient(180deg, var(--surface-from), var(--surface-gradient-to, var(--surface-to)));
}

/* Hard pixel text shadow, reads --c-text-shadow when set by colorStyle() */
@utility text-shadow-pixel {
  text-shadow: var(--c-text-shadow, 2px 2px 0 rgba(0, 0, 0, 0.5));
}
/* 1px shadow for text 18px and below */
@utility text-shadow-pixel-xs {
  text-shadow: var(--c-text-shadow-xs, 1px 1px 0 rgba(0, 0, 0, 0.5));
}

/* ---------------------------------------------------------------------------
   Theme tokens + keyframes
   --------------------------------------------------------------------------- */
@theme {
  /* Fonts: m6x11plus is the only font. font-sans and font-pixel are the same. */
  --font-sans: "m6x11plus", ui-monospace, monospace;
  --font-pixel: "m6x11plus", ui-monospace, monospace;

  /* UI type scale. Used by every control (text-ui-*).
     Line heights are whole pixels so no control gets a fractional height. */
  --text-ui-xs: 12px;
  --text-ui-xs--line-height: 14px;
  --text-ui-sm: 18px;
  --text-ui-sm--line-height: 20px;
  --text-ui-md: 22px;
  --text-ui-md--line-height: 24px;
  --text-ui-lg: 28px;
  --text-ui-lg--line-height: 32px;
  --text-ui-xl: 36px;
  --text-ui-xl--line-height: 40px;
  --text-ui-2xl: 48px;
  --text-ui-2xl--line-height: 52px;

  --animate-rotate-lift: rotate-lift 2.4s ease-in-out infinite;
  --animate-rainbow-gradient: rainbow 1s ease-in-out infinite;
  --animate-bounce-soft: bounce-soft 1s linear infinite;
  --animate-spin-steps: spin 0.8s steps(8) infinite;
  --animate-pop: pop 0.15s ease-out both;
  --animate-toast-in: toast-in 0.2s ease-out both;
  --animate-toast-out: toast-out 0.2s ease-in both;

  --shadow-soft: 0px 6px 0 rgba(0, 0, 0, 0.25);
  --shadow-soft-hover: 0px 6px 1px rgba(0, 0, 0, 0.25);
  --shadow-hard: 4px 4px 0 rgba(0, 0, 0, 0.25);

  @keyframes rotate-lift {
    20% {
      transform: translateY(0) rotate(6deg);
    }
  }

  @keyframes rainbow {
    0% {
      background-position: 0% 50%;
    }
    100% {
      background-position: 200% 50%;
    }
  }

  @keyframes pop {
    from {
      opacity: 0;
      transform: scale(0.85);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes toast-in {
    from {
      opacity: 0;
      transform: translateX(120%);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes toast-out {
    from {
      opacity: 1;
      transform: translateX(0);
    }
    to {
      opacity: 0;
      transform: translateX(120%);
    }
  }

  @keyframes bounce-soft {
    0%,
    100% {
      transform: translateY(0) rotate(0);
    }
    33% {
      transform: translateY(-2.5%) rotate(1deg);
    }
    66% {
      transform: translateY(0) rotate(-1deg);
    }
  }

}

/* ---------------------------------------------------------------------------
   Reduced motion: stop all decorative motion.
   --------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ---------------------------------------------------------------------------
   Small text (18px and below) always gets a 1px shadow. Light surfaces set
   --c-text-shadow-xs to none; colored elements set it via colorStyle().
   --------------------------------------------------------------------------- */
.text-ui-xs,
.text-xs,
.text-ui-sm,
.text-sm {
  text-shadow: var(--c-text-shadow-xs, 1px 1px 0 rgba(0, 0, 0, 0.5));
}

/* ===========================================================================
   GENERAL STYLE
   Every control shares: rounded-(--radius), 4px black border, vertical gradient,
   inner highlight, hard 4px shadow, pixel font, squish on press.
   Colors come from the --c-* variables (see components/palette.ts).
   =========================================================================== */

/* Buttons ------------------------------------------------------------------ */
.btn {
  @apply relative top-0 inline-flex max-w-full cursor-pointer items-center justify-center gap-2.5 rounded-(--radius) border-(length:--border-w) border-(--border-color) font-pixel font-medium tracking-wide whitespace-nowrap shadow-[var(--btn-highlight),var(--shadow-hard)] outline-neutral-500/25 transition-all duration-75 ease-in-out select-none hover:-top-1 hover:scale-105 hover:animate-bounce-soft focus-visible:scale-105 focus-visible:animate-bounce-soft focus-visible:outline-4 focus-visible:outline-offset-0 focus-visible:outline-white/70 active:top-0 active:scale-x-110 active:scale-y-90 [&_svg]:size-6 [&_svg]:shrink-0 [&_svg]:drop-shadow-(--c-icon-shadow) px-4 py-1.5 pb-2.5 text-ui-md text-shadow-pixel;
  background-image: linear-gradient(180deg, var(--c-from, #71717a), var(--gradient-to, var(--c-to, #52525b)));
  color: var(--c-text, #fff);
}
.btn-lg {
  @apply gap-3 px-5 py-2 pb-3 text-ui-lg [&_svg]:size-8 text-shadow-pixel ;
}
/* Icon-only: square */
.btn-icon {
  @apply size-11 p-0;
}
.btn-icon.btn-lg {
  @apply size-14 p-0;
}
.btn-content {
  @apply inline-flex items-center gap-[inherit];
}
.btn:disabled,
.btn.is-disabled {
  @apply pointer-events-none top-1 opacity-50 saturate-50 shadow-[inset_0_0_0_4px_rgba(255,255,255,.2)];
}
.btn.is-loading {
  @apply pointer-events-none;
}
.btn.is-loading .btn-content {
  @apply opacity-0;
}
.btn-spinner {
  @apply absolute inset-0 flex items-center justify-center;
}
.btn-spinner svg {
  @apply animate-spin-steps;
}

/* Text inputs ------------------------------------------------------------- */
@utility input-base {
  @apply relative top-0 flex w-full max-w-lg items-center gap-2.5 rounded-(--radius) border-(length:--border-w) border-(--border-color) px-4 py-2 font-pixel text-ui-md font-medium tracking-wide transition-all duration-75 ease-in-out hover:-top-1 hover:scale-[1.03] focus-within:scale-[1.03] focus-within:animate-bounce-soft focus-within:outline-4 focus-within:outline-offset-0 [&_input]:min-w-0 [&_input]:flex-1 [&_input]:bg-transparent [&_input]:outline-none [&_svg]:relative [&_svg]:top-px [&_svg]:size-6 [&_svg]:shrink-0;
}

.input-light {
  @apply input-base bg-surface text-(--surface-text) shadow-[inset_0_0_0_4px_var(--surface-highlight),var(--shadow-hard)] outline-neutral-500/25 placeholder:text-(--surface-muted) focus-within:shadow-soft-hover focus-within:outline-zinc-400 [&_input]:placeholder:text-(--surface-muted);
}

.input-dark {
  @apply input-base border-black/80 bg-black/80 text-white shadow-soft outline-neutral-500/25 placeholder:text-white/40 focus-within:shadow-soft-hover focus-within:outline-white/50 [&_input]:placeholder:text-white/40 [&_svg]:drop-shadow-[3px_3px_0_rgba(0,0,0,.5)];
}

/* Large input: 10 + 10 padding + 32 line height + 8 border = 60px, same as .btn-lg */
.input-lg {
  @apply gap-3 px-5 py-2.5 text-ui-lg [&_svg]:size-8;
}

.input-area {
  @apply min-h-28 resize-y focus-within:animate-none;
}

.input-select {
  @apply cursor-pointer appearance-none pr-12 [&_option]:bg-(--surface-from) [&_option]:text-(--surface-text) [&_option]:[text-shadow:var(--surface-text-shadow)];
}

/* Number stepper: two icon buttons with the number between them */
.stepper {
  @apply inline-flex items-center gap-3 font-pixel text-ui-lg tracking-wide text-white [text-shadow:_3px_3px_0_rgba(0,0,0,.5)];
}
.stepper input {
  @apply w-12 bg-transparent text-center outline-none [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none;
}
.stepper input:disabled {
  @apply opacity-50;
}
/* Inside a light panel: dark number, no shadow */
.panel .stepper {
  @apply text-(--surface-text) [text-shadow:var(--surface-text-shadow)];
}

/* Choice controls --------------------------------------------------------- */
/* The label stays still; only the box / track lifts and squishes. */
.choice-field {
  @apply relative inline-flex cursor-pointer items-center gap-2.5 font-pixel text-ui-md tracking-wide text-white select-none [text-shadow:_3px_3px_0_rgba(0,0,0,.5)];
}
.choice-field input {
  @apply sr-only;
}

.choice-box {
  @apply relative flex size-8 shrink-0 items-center justify-center rounded-(--radius-sm) border-(length:--border-w) border-(--border-color) bg-surface shadow-[inset_0_0_0_3px_var(--surface-highlight),var(--shadow-hard)] transition-all duration-75 ease-in-out;
}
.choice-field:hover .choice-box {
  @apply -translate-y-1 scale-105;
}
.choice-field:active .choice-box {
  @apply translate-y-0 scale-x-110 scale-y-95;
}
.choice-box.is-radio {
  @apply rounded-full;
}
.choice-box svg {
  @apply size-6 scale-50 text-white opacity-0 drop-shadow-[2px_2px_0_rgba(0,0,0,.5)] transition-all duration-75 ease-in-out;
}
.choice-box.is-radio::after {
  content: '';
  @apply size-2.5 scale-0 rounded-full bg-white shadow-[2px_2px_0_rgba(0,0,0,.4)] transition-transform duration-75 ease-in-out;
}
.choice-field:has(:checked) .choice-box {
  @apply bg-none bg-(--accent,#22c55e) shadow-[inset_0_0_0_3px_rgba(255,255,255,.25),var(--shadow-hard)];
}
.choice-field:has(:checked) .choice-box svg {
  @apply scale-100 opacity-100;
}
.choice-field:has(:checked) .choice-box.is-radio::after {
  @apply scale-100;
}
.choice-field:has(:focus-visible) .choice-box,
.choice-field:has(:focus-visible) .toggle-track {
  @apply outline-4 outline-offset-2 outline-white/70;
}
.choice-field:has(:disabled) {
  @apply cursor-not-allowed opacity-50;
}
.choice-field:has(:disabled) .choice-box,
.choice-field:has(:disabled) .toggle-track {
  @apply translate-y-0 scale-100;
}

/* Toggle */
.toggle-track {
  @apply relative h-8 w-14 shrink-0 rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-black/50 shadow-[inset_0_3px_0_rgba(0,0,0,.4),var(--shadow-hard)] transition-all duration-75 ease-in-out;
}
.choice-field:hover .toggle-track {
  @apply -translate-y-1 scale-105;
}
.choice-field:active .toggle-track {
  @apply translate-y-0 scale-x-110 scale-y-95;
}
.toggle-track::after {
  content: '';
  @apply absolute top-0.5 left-0.5 size-5 rounded-(--radius-sm) border-(length:--border-w-sm) border-(--border-color) bg-surface shadow-[inset_0_0_0_2px_var(--surface-highlight),2px_2px_0_rgba(0,0,0,.4)] transition-all duration-75 ease-in-out;
}
.choice-field:has(:checked) .toggle-track {
  @apply bg-(--accent,#22c55e) shadow-[inset_0_3px_0_rgba(0,0,0,.2),var(--shadow-hard)];
}
.choice-field:has(:checked) .toggle-track::after {
  @apply left-[26px] scale-x-110;
}
.choice-field:active .toggle-track::after {
  @apply scale-x-125;
}

/* Slider (native range). --fill is set by the Slider component script. */
.slider {
  @apply relative top-0 h-9 w-full max-w-lg cursor-pointer appearance-none bg-transparent transition-all duration-75 ease-in-out select-none hover:-top-1 hover:scale-[1.03] focus-visible:outline-none;
}
.slider::-webkit-slider-runnable-track {
  @apply h-5 rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-black/50 shadow-[inset_0_3px_0_rgba(0,0,0,.4),var(--shadow-hard)];
  background-image: linear-gradient(var(--accent, #22c55e), var(--accent, #22c55e));
  background-size: var(--fill, 50%) 100%;
  background-repeat: no-repeat;
}
.slider::-moz-range-track {
  @apply h-5 rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-black/50 shadow-[inset_0_3px_0_rgba(0,0,0,.4),var(--shadow-hard)];
}
.slider::-moz-range-progress {
  @apply h-3 rounded-l-md bg-(--accent,#22c55e);
}
.slider::-webkit-slider-thumb {
  @apply -mt-[10px] size-8 cursor-grab appearance-none rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-surface shadow-[inset_0_0_0_3px_var(--surface-highlight),var(--shadow-hard)] transition-all duration-75 ease-in-out;
}
.slider::-moz-range-thumb {
  @apply size-8 cursor-grab rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-surface shadow-[inset_0_0_0_3px_var(--surface-highlight),var(--shadow-hard)] transition-all duration-75 ease-in-out;
}
.slider:hover::-webkit-slider-thumb {
  @apply scale-110;
}
.slider:hover::-moz-range-thumb {
  @apply scale-110;
}
.slider:active::-webkit-slider-thumb,
.slider.is-dragging::-webkit-slider-thumb {
  @apply scale-x-140 scale-y-75 cursor-grabbing shadow-[inset_0_0_0_3px_rgba(255,255,255,.2),var(--shadow-hard-sm)];
}
.slider:active::-moz-range-thumb,
.slider.is-dragging::-moz-range-thumb {
  @apply scale-x-140 scale-y-75 cursor-grabbing shadow-[inset_0_0_0_3px_rgba(255,255,255,.2),var(--shadow-hard-sm)];
}
.slider.is-dragging {
  @apply top-0 scale-100;
}
.slider:focus-visible::-webkit-slider-thumb {
  @apply outline-4 outline-offset-2 outline-white/70;
}
.slider:focus-visible::-moz-range-thumb {
  @apply outline-4 outline-offset-2 outline-white/70;
}

/* Panel + dialog ---------------------------------------------------------- */
.panel {
  @apply w-full max-w-lg overflow-hidden rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-surface text-(--surface-text) shadow-[inset_0_0_0_4px_var(--surface-highlight),var(--shadow-hard-lg)];
}
.panel-title {
  @apply flex items-center gap-2.5 border-b-(length:--border-w) border-(--border-color) px-4 py-3 font-pixel text-ui-md tracking-wide text-shadow-pixel [&>svg]:size-6 [&>svg]:shrink-0 [&>svg]:drop-shadow-(--c-icon-shadow);
  background-image: linear-gradient(180deg, var(--c-from, #71717a), var(--gradient-to, var(--c-to, #52525b)));
  color: var(--c-text, #fff);
}
.panel-title > .btn {
  @apply ml-auto;
}
.panel-body {
  @apply flex flex-col gap-4 p-6 text-ui-md tracking-wide;
  text-shadow: var(--surface-text-shadow);
  --c-text-shadow-xs: var(--surface-text-shadow-xs);
}
.panel-footer {
  @apply flex flex-wrap items-center justify-end gap-3 border-t-(length:--border-w) border-(--surface-line) bg-(--surface-inset) px-4 py-3;
  --c-text-shadow-xs: var(--surface-text-shadow-xs);
}
/* Controls inside a light panel: dark text, no text shadow */
.panel .choice-field,
.panel .story-label {
  @apply text-(--surface-text) [text-shadow:var(--surface-text-shadow)];
}

.dialog {
  @apply m-auto max-w-[calc(100vw-2rem)] overflow-visible bg-transparent p-2 open:animate-pop;
}
.dialog::backdrop {
  @apply bg-black/60;
}

/* Tabs ---------------------------------------------------------------------- */
.tab-list {
  @apply flex flex-wrap gap-2 rounded-(--radius) bg-black/50 p-2 shadow-[inset_0_3px_0_rgba(0,0,0,.4)];
}
.tab {
  @apply flex cursor-pointer items-center gap-1.5 rounded-(--radius-sm) px-3 py-1 font-pixel text-ui-md tracking-wide text-white transition-all duration-75 select-none hover:bg-white/25 hover:scale-105 active:scale-x-125 active:scale-y-75 focus-visible:outline-2 focus-visible:outline-white/70 aria-selected:bg-surface aria-selected:text-(--surface-text) aria-selected:shadow-[2px_2px_0_rgba(0,0,0,.4)] [&_svg]:size-5 text-shadow-pixel;
}
.tab[aria-selected="true"] {
  @apply text-shadow-[none];
}
.tab[aria-selected='true'] {
  --c-text-shadow-xs: var(--surface-text-shadow-xs);
}
.tab-panel[hidden] {
  display: none;
}

/* Dropdown menu ------------------------------------------------------------- */
.dropdown {
  @apply relative inline-block;
}
.dropdown > summary {
  @apply list-none [&::-webkit-details-marker]:hidden;
}
.dropdown > summary svg:last-child {
  @apply transition-transform duration-75;
}
.dropdown[open] > summary svg:last-child {
  @apply rotate-180;
}
.dropdown-menu {
  @apply absolute top-full left-0 z-40 mt-2 flex min-w-48 animate-pop flex-col gap-0.5 rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-surface p-1.5 shadow-[inset_0_0_0_3px_var(--surface-highlight),var(--shadow-hard-lg)];
}
.dropdown-menu {
  --c-text-shadow-xs: var(--surface-text-shadow-xs);
}
.dropdown.is-right .dropdown-menu {
  @apply right-0 left-auto;
}
.dropdown-item {
  @apply flex w-full cursor-pointer items-center gap-3 rounded-(--radius-sm) px-3 py-2 text-left font-pixel text-ui-md tracking-wide text-(--surface-text) transition-colors duration-75 hover:bg-(--surface-hover) focus-visible:bg-(--surface-hover) focus-visible:outline-none [&_svg]:size-6 [&_svg]:shrink-0;
  text-shadow: var(--surface-text-shadow);
}
.dropdown-item.is-danger {
  @apply text-red-600;
}
.dropdown-divider {
  @apply my-1 h-0.5 bg-(--surface-line);
}

/* Progress ------------------------------------------------------------------ */
.progress {
  @apply relative w-full max-w-lg overflow-hidden rounded-(--radius) border-(length:--border-w) border-(--border-color) bg-black/50 shadow-[inset_0_3px_0_rgba(0,0,0,.4),var(--shadow-hard)];
}
.progress-sm {
  @apply h-4;
}
.progress-md {
  @apply h-7;
}
.progress-lg {
  @apply h-9;
}
.progress-fill {
  @apply h-full rounded-sm shadow-[inset_0_3px_0_rgba(255,255,255,.35)] transition-[width] duration-300 ease-out;
  background-image: linear-gradient(180deg, var(--c-from, #22c55e), var(--gradient-to, var(--c-to, #16a34a)));
}
.progress-segments {
  @apply pointer-events-none absolute inset-0;
  background-image: repeating-linear-gradient(
    90deg,
    transparent 0,
    transparent calc(var(--seg) - 3px),
    rgba(0, 0, 0, 0.45) calc(var(--seg) - 3px),
    rgba(0, 0, 0, 0.45) var(--seg)
  );
}
.progress-label {
  @apply pointer-events-none absolute inset-0 flex items-center justify-center font-pixel text-ui-sm tracking-wide text-white text-shadow-pixel-xs;
}
.progress-row {
  @apply flex w-full max-w-lg items-center gap-3 font-pixel text-ui-sm tracking-wide text-white text-shadow-pixel-xs [&>svg]:size-6 [&>svg]:shrink-0 [&>svg]:drop-shadow-[2px_2px_0_rgba(0,0,0,.5)];
}
.panel .progress-row {
  @apply text-(--surface-text) [text-shadow:var(--surface-text-shadow)] [&>svg]:drop-shadow-(--surface-icon-shadow);
}

/* Badge / key cap ------------------------------------------------------------ */
.badge {
  @apply inline-flex items-center justify-center gap-1 rounded-(--radius-sm) border-(length:--border-w-sm) border-(--border-color) font-pixel tracking-wide whitespace-nowrap shadow-[inset_0_0_0_2px_rgba(255,255,255,.2),var(--shadow-hard-sm)] text-shadow-pixel-xs [&_svg]:drop-shadow-(--c-icon-shadow);
  background-image: linear-gradient(180deg, var(--c-from, #71717a), var(--gradient-to, var(--c-to, #52525b)));
  color: var(--c-text, #fff);
}
.badge-sm {
  @apply min-w-[22px] px-1.5 py-0.5 text-ui-xs [&_svg]:size-3;
}
.badge-md {
  @apply min-w-7 px-2 py-0.5 pb-1 text-ui-sm [&_svg]:size-4;
}
.badge.is-pill {
  @apply rounded-full;
}
.badge.is-pulse {
  @apply animate-bounce-soft;
}

.keycap {
